// Arma el correo en español con estilos en línea. TODO texto dinámico se escapa.
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const mxn = (n) => new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN' }).format(Number(n || 0));
const fecha = (d) => { const [y, m, day] = String(d).slice(0, 10).split('-'); return `${day}/${m}/${y}`; };
const wrap = (title, body) => `<div style="font-family:Arial,Helvetica,sans-serif;color:#0F172A;max-width:640px;margin:0 auto"><div style="background:#1E3A8A;color:#fff;padding:14px 18px;font-size:18px;font-weight:700">CRM-123</div><div style="padding:18px"><h2 style="margin:0 0 12px;font-size:18px">${esc(title)}</h2>${body}</div></div>`;
const section = (title, rows) => rows.length ? `<h3 style="font-size:15px;margin:18px 0 6px">${esc(title)}</h3><ul style="padding-left:18px;margin:0">${rows.map((r) => `<li style="margin:4px 0">${r}</li>`).join('')}</ul>` : '';

return $input.all().map((item) => {
  const r = item.json;
  const d = r.data || {};
  let html;
  if (r.kind === 'supervisor') {
    const k = d.team_kpis || {};
    const kpis = [
      ['Pipeline abierto', `${esc(k.open_opportunities)} oportunidades · ${mxn(k.open_pipeline_premium)}`],
      ['Ganado del mes', `${esc(k.won_count_month)} ganadas · ${mxn(k.won_premium_month)}`],
      ['Recibos vencidos', esc(k.overdue_receipts)],
      ['Renovaciones próximas', esc(k.upcoming_renewals)],
      ['Siniestros abiertos', esc(k.open_claims)],
      ['Seguimientos vencidos', esc(k.overdue_follow_ups)],
    ].map(([a, b]) => `<tr><td style="padding:6px 8px;border-bottom:1px solid #E2E8F0">${a}</td><td style="padding:6px 8px;border-bottom:1px solid #E2E8F0;text-align:right"><b>${b}</b></td></tr>`).join('');
    const rank = (d.ranking || []).map((s, i) => `<tr><td style="padding:6px 8px;border-bottom:1px solid #E2E8F0">${i + 1}. ${esc(s.seller_name)}</td><td style="padding:6px 8px;border-bottom:1px solid #E2E8F0;text-align:right">${mxn(s.won_premium_month)}${s.goal_premium_month ? ' de ' + mxn(s.goal_premium_month) : ''}</td></tr>`).join('');
    html = wrap('Resumen del equipo', `<table style="width:100%;border-collapse:collapse;font-size:14px">${kpis}</table><h3 style="font-size:15px;margin:18px 0 6px">Ranking de vendedores del mes</h3><table style="width:100%;border-collapse:collapse;font-size:14px">${rank || '<tr><td>Sin datos.</td></tr>'}</table>`);
  } else {
    const hoy = (d.follow_ups_today || []).map((f) => `<b>${esc(f.client_name)}</b> · ${esc(f.note || 'Sin nota')}`);
    const venc = (d.follow_ups_overdue || []).map((f) => `<b>${esc(f.client_name)}</b> · ${fecha(f.due_date)} · ${esc(f.note || 'Sin nota')}`);
    const rec = (d.receipts || []).map((x) => `Póliza <b>${esc(x.policy_number)}</b> · ${esc(x.client_name || 'Cliente reasignado')} · recibo ${esc(x.installment_number)} · ${fecha(x.due_date)} · ${mxn(x.amount)} · ${Number(x.days_to_due) < 0 ? 'vencido' : 'vence en ' + esc(x.days_to_due) + ' días'}`);
    const ren = (d.renewals || []).map((x) => `Póliza <b>${esc(x.policy_number)}</b> · ${esc(x.client_name || 'Cliente reasignado')} · ${esc(x.product_name)} · termina ${fecha(x.end_date)} (${esc(x.days_to_end)} días)`);
    const body = section('Seguimientos de hoy', hoy) + section('Seguimientos vencidos', venc) + section('Recibos vencidos o por vencer', rec) + section('Renovaciones próximas', ren);
    html = wrap(`Hola, ${String(r.name || '').split(' ')[0]}`, body || '<p>Sin pendientes hoy.</p>');
  }
  return { json: { user_id: r.user_id, deliver_to: r.deliver_to, subject: r.subject, html } };
});

// Une cada respuesta de Resend con su destinatario (mismo orden que "Armar correo").
const built = $('Armar correo').all();
const data = $('Obtener datos').first().json;
const sent = [];
const failed = [];
$input.all().forEach((item, i) => {
  const user_id = built[i]?.json?.user_id;
  if (!user_id) return;
  if (item.json && item.json.id && !item.json.error) sent.push({ user_id, resend_id: String(item.json.id) });
  else failed.push({ user_id, error: String((item.json && (item.json.error?.message || item.json.message || item.json.error)) || 'Error desconocido').slice(0, 200) });
});
return [{ json: { run_id: data.run_id, mode: data.mode, sent, failed } }];
